roots = repo.list(".")
out = {"root": roots}
for name in ["tests/", "src/", "benches/", "examples/"]:
    if name in roots:
        out[name] = repo.list(name)
if "tests/" in roots:
    for f in repo.list("tests"):
        if not f.endswith("/"):
            out["tests/" + f] = repo.read("tests/" + f)
return out

